import {
  normaliseHash
} from "./chunk-YNBT6XVD.js";

// src/constants.ts
var DEFAULT_RETRY_COUNT = 3;
var CERTIFICATE_REGISTRY_ID = 1;
var PACKAGED_CERTIFICATES_URL_MAINNET = "https://certificates.zkpassport.id/mainnet";
var PACKAGED_CERTIFICATES_URL_SEPOLIA = "https://certificates.zkpassport.id/sepolia";
var PACKAGED_CERTIFICATES_URL_DEV = "http://localhost:3000/certificates";
var PACKAGED_CERTIFICATES_URL_TEMPLATE = (chainId, root, cid) => {
  if (cid) {
    return `https://ipfs.infura.io/ipfs/${cid}`;
  }
  root = normaliseHash(root);
  if (chainId === 1) {
    return `${PACKAGED_CERTIFICATES_URL_MAINNET}/${root}.json`;
  } else if (chainId === 11155111) {
    return `${PACKAGED_CERTIFICATES_URL_SEPOLIA}/${root}.json`;
  } else {
    return `${PACKAGED_CERTIFICATES_URL_DEV}/${root}.json`;
  }
};
var CIRCUIT_URL_MAINNET = "https://circuits2.zkpassport.id/mainnet";
var CIRCUIT_URL_SEPOLIA = "https://circuits2.zkpassport.id/sepolia";
var CIRCUIT_URL_DEV = "http://localhost:3000";
var CIRCUIT_MANIFEST_URL_TEMPLATE = (chainId, { root, version, cid }) => {
  if (root) {
    root = normaliseHash(root);
    if (chainId === 1) {
      return `${CIRCUIT_URL_MAINNET}/by-root/${root}/manifest.json`;
    } else if (chainId === 11155111) {
      return `${CIRCUIT_URL_SEPOLIA}/by-root/${root}/manifest.json`;
    } else {
      return `${CIRCUIT_URL_DEV}/by-root/${root}/manifest.json`;
    }
  } else if (version) {
    if (chainId === 1) {
      return `${CIRCUIT_URL_MAINNET}/by-version/${version}/manifest.json`;
    } else if (chainId === 11155111) {
      return `${CIRCUIT_URL_SEPOLIA}/by-version/${version}/manifest.json`;
    } else {
      return `${CIRCUIT_URL_DEV}/by-version/${version}/manifest.json`;
    }
  } else if (cid) {
    return `https://ipfs.infura.io/ipfs/${cid}`;
  } else {
    throw new Error("No root, version or cid provided");
  }
};
var PACKAGED_CIRCUIT_URL_TEMPLATE = (chainId, hash, cid) => {
  if (cid) {
    return `https://ipfs.infura.io/ipfs/${cid}`;
  }
  hash = normaliseHash(hash);
  if (chainId === 1) {
    return `${CIRCUIT_URL_MAINNET}/by-hash/${hash}.json`;
  } else if (chainId === 11155111) {
    return `${CIRCUIT_URL_SEPOLIA}/by-hash/${hash}.json`;
  } else {
    return `${CIRCUIT_URL_DEV}/by-hash/${hash}.json`;
  }
};
var DEFAULT_HISTORICAL_ROOTS_PAGE_SIZE = 100;
var LATEST_ROOT_SIGNATURE = "0xd7b0fef1";
var LATEST_ROOT_WITH_PARAM_SIGNATURE = "0xc3bc16e8";
var GET_HISTORICAL_ROOTS_SIGNATURE = "0x06ac4103";
var GET_HISTORICAL_ROOTS_BY_HASH_SIGNATURE = "0xcb0c82c7";
var GET_LATEST_ROOT_DETAILS_SIGNATURE = "0x76785af8";
var REGISTRIES_MAPPING_SIGNATURE = "0x5d8d57a6";
var GET_ROOT_DETAILS_BY_ROOT_SIGNATURE = "0xbb3dd539";
var IS_ROOT_VALID_SIGNATURE = "0x83578c11";

export {
  DEFAULT_RETRY_COUNT,
  CERTIFICATE_REGISTRY_ID,
  PACKAGED_CERTIFICATES_URL_MAINNET,
  PACKAGED_CERTIFICATES_URL_SEPOLIA,
  PACKAGED_CERTIFICATES_URL_DEV,
  PACKAGED_CERTIFICATES_URL_TEMPLATE,
  CIRCUIT_URL_MAINNET,
  CIRCUIT_URL_SEPOLIA,
  CIRCUIT_URL_DEV,
  CIRCUIT_MANIFEST_URL_TEMPLATE,
  PACKAGED_CIRCUIT_URL_TEMPLATE,
  DEFAULT_HISTORICAL_ROOTS_PAGE_SIZE,
  LATEST_ROOT_SIGNATURE,
  LATEST_ROOT_WITH_PARAM_SIGNATURE,
  GET_HISTORICAL_ROOTS_SIGNATURE,
  GET_HISTORICAL_ROOTS_BY_HASH_SIGNATURE,
  GET_LATEST_ROOT_DETAILS_SIGNATURE,
  REGISTRIES_MAPPING_SIGNATURE,
  GET_ROOT_DETAILS_BY_ROOT_SIGNATURE,
  IS_ROOT_VALID_SIGNATURE
};
